<?php
declare(strict_types=1);
$root=dirname(__DIR__);spl_autoload_register(function($class)use($root){foreach(['CajeerEngine\\'=>'core/','CajeerBook\\'=>'src/'] as $prefix=>$dir)if(str_starts_with($class,$prefix)){$f=$root.'/'.$dir.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($f))require_once $f;return;}});
use CajeerBook\{ApiPlayground as P,BookStore,OpenApiDocument,OpenApiStore,SdkBuilder as S,Visibility};
function check(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);echo "PASS $label\n";}
function cleanSdk(string $p):void{if(!is_dir($p))return;foreach(new DirectoryIterator($p) as $f){if($f->isDot())continue;if($f->isDir()&&!$f->isLink())cleanSdk($f->getPathname());else unlink($f->getPathname());}rmdir($p);}
$dir=sys_get_temp_dir().'/book-sdk-test-'.bin2hex(random_bytes(8));mkdir($dir,0700);
try{
    $origin=$argv[1]??'https://api.example.org';$out=$argv[2]??null;
    $source=function(string $base,string $summary='Create pet'):OpenApiDocument{
        $spec=json_decode(<<<'JSON'
{"openapi":"3.1.0","info":{"title":"Pets API","version":"1"},"servers":[{"url":"https://api.example.org/v1"}],"security":[{"token":[],"queryKey":[]},{"basic":[]},{}],"components":{"securitySchemes":{"token":{"type":"http","scheme":"bearer"},"queryKey":{"type":"apiKey","in":"query","name":"key"},"basic":{"type":"http","scheme":"basic"}}},"paths":{"/pets/{id}":{"post":{"summary":"Create pet","parameters":[{"name":"id","in":"path","required":true,"schema":{"type":"string"}},{"name":"limit","in":"query","required":true,"schema":{"type":"integer"}},{"name":"X-Trace","in":"header","schema":{"type":"string"}},{"name":"theme","in":"cookie","schema":{"type":"string"}}],"requestBody":{"required":true,"content":{"application/json":{"schema":{"type":"object"}}}},"responses":{"201":{"description":"Created"}}}},"/redirect":{"get":{"responses":{"302":{"description":"Redirect"}}}},"/binary":{"get":{"responses":{"200":{"description":"Binary"}}}},"/large":{"get":{"responses":{"200":{"description":"Large"}}}},"/hidden":{"get":{"responses":{"200":{"description":"Draft only"}}}},"/unsupported":{"get":{"parameters":[{"name":"obj","in":"query","schema":{"type":"object"}}],"responses":{"200":{"description":"OK"}}}}}}
JSON,false,64,JSON_THROW_ON_ERROR);$spec->servers[0]->url=$base.'/v1';$spec->paths->{'/pets/{id}'}->post->summary=$summary;return new OpenApiDocument('openapi.json',['openapi.json'=>OpenApiDocument::json($spec)]);
    };
    $store=new BookStore($dir.'/store');$store->change(fn(&$db)=>$db['pages']=[]);$api=new OpenApiStore($store);$writer=['id'=>str_repeat('a',32),'username'=>'writer','role'=>'editor'];$admin=['id'=>str_repeat('b',32),'username'=>'admin','role'=>'admin'];$owner=['id'=>str_repeat('c',32),'username'=>'owner','role'=>'owner'];$users=array_column([$writer,$admin,$owner],null,'id');$store->review($owner,$users,'policy',['required'=>'1','revision'=>'1']);
    $apply=function($doc)use($api,$writer){$p=$api->preview($doc,'api','1','pets','secret');$api->apply($p['bundle'],'api','1','pets','secret',$p['token'],$writer);};$apply($source($origin));
    $key='api/1/reference/pets/operations/post-'.substr(hash('sha256','/pets/{id}'),0,24);$db=$store->read();check(S::collect($db,Visibility::pages($db,'public','none'),$key)===null,'draft operation cannot generate SDK');
    foreach(['/pets/{id}'=>'post','/redirect'=>'get','/binary'=>'get','/large'=>'get','/unsupported'=>'get'] as $path=>$method){$k='api/1/reference/pets/operations/'.$method.'-'.substr(hash('sha256',$path),0,24);$rid=$store->review($writer,$users,'submit',['kind'=>'page','target'=>$k,'expected'=>'1','reviewer'=>$admin['id']]);$store->review($admin,$users,'approve',['id'=>$rid,'revision'=>'1']);$store->review($owner,$users,'publish',['id'=>$rid,'revision'=>'2']);}
    $db=$store->read();$visible=Visibility::pages($db,'public','none');$m=S::collect($db,$visible,$key);check(count($m['operations'])===4,'only supported published operations included');check(S::collect($db,Visibility::pages($db,'private','none'),$key)===null,'private workspace denies SDK');
    $examples=S::examples($m);check(str_contains($examples['curl'],'YOUR_API_CREDENTIAL')&&str_contains($examples['typescript'],$m['selected'])&&str_contains($examples['python'],$m['selected'])&&str_contains($examples['php'],$m['selected']),'examples generated from selected operation');
    foreach(S::LANGUAGES as $lang){$files=S::files($m,$lang);$bytes=S::archive($m,$lang);check(str_starts_with($bytes,'PK')&&str_contains($files['publication.json'],$m['version'])&&!str_contains($files['operations.json'],'/hidden')&&!str_contains($files['operations.json'],'/unsupported'),'valid '.$lang.' SDK publication package');if($out!==null)file_put_contents($out.'/'.$lang.'.zip',$bytes);}
    if($out!==null)file_put_contents($out.'/model.json',OpenApiDocument::json($m));
    $apply($source('https://draft.example.org','Unpublished target'));$db=$store->read();$new=S::collect($db,Visibility::pages($db,'public','none'),$key);check($new['version']===$m['version']&&$new['definitions']===$m['definitions'],'draft update does not change SDK publication digest');
    $rid=$store->review($writer,$users,'submit',['kind'=>'page','target'=>$key,'expected'=>(string)$db['pages'][$key]['revision'],'reviewer'=>$admin['id']]);$store->review($admin,$users,'approve',['id'=>$rid,'revision'=>'1']);$store->review($owner,$users,'publish',['id'=>$rid,'revision'=>'2']);$db=$store->read();$new=S::collect($db,Visibility::pages($db,'public','none'),$key);check($new['version']!==$m['version']&&$new['definitions'][$m['selected']]['servers']===['https://draft.example.org/v1'],'approved publication changes version and operation');
}finally{cleanSdk($dir);}
